INSERT INTO manufacturers (id, name, legal_name, website, notes) VALUES
(6, 'Fabricante não identificado (Linha MP / Módulo Prático)', NULL, NULL, 'Linha usada na planilha interna PlanilhaEsquadrias101.xlsx (abas MENU MP / MENU LINHA 30), fabricante real não confirmado em nenhuma fonte processada.'),
(7, 'Fabricante não identificado (Linha Portão)', NULL, NULL, 'Linha de portões de correr usada na planilha interna PlanilhaEsquadrias101.xlsx (aba MENU PORTÃO), fabricante real não confirmado.');
INSERT INTO product_lines (id, manufacturer_id, name, description, origin_type, status_code) VALUES
(7, 6, 'Módulo Prático / Linha 30', 'Perfis MP-xxx usados nas abas de janela/porta de correr e maxim-ar da planilha interna.', 'ENCONTRADO_DOCUMENTO', 'NECESSITA_CONFERENCIA'),
(8, 7, 'Linha Portão', 'Perfis PC-xxx/PU-xxx/LB-xxx usados nas abas de portão de correr da planilha interna.', 'ENCONTRADO_DOCUMENTO', 'NECESSITA_CONFERENCIA'),
(9, 1, 'Linha Moveleira', 'Linha citada na contracapa do catálogo Ecoline 2.5 (fabricante Perfil Alumínio do Brasil) para armários/gaveteiros com portas de giro em alumínio e vidro; perfis usados nas abas de gaveteiro/armário da planilha interna.', 'ENCONTRADO_DOCUMENTO', 'NECESSITA_CONFERENCIA');
INSERT INTO technical_sources (id, manufacturer_id, title, file_name, document_type, is_uploaded, notes) VALUES
(10, NULL, 'Planilha interna de cálculo de corte (PlanilhaEsquadrias101.xlsx)', 'c05ff497-690676096PlanilhaEsquadrias101.xlsx', 'PLANILHA', 1, 'Ferramenta de cálculo em uso pelo próprio usuário. 76 abas de tipologia processadas, 772 fórmulas de TAMANHO extraídas e resolvidas simbolicamente (L=largura do vão, A=altura do vão, N=quantidade). Fórmulas em unidades de compra/estampagem (IF/ROUNDUP/SUM) não foram convertidas — não são fórmulas de corte.');
INSERT INTO typologies (id, name, category, is_common_in_brazil, notes, source_reference_id) VALUES
(10, 'Portão de Correr', 'PORTAO', 1, 'Identificado na planilha interna do usuário (não fazia parte do briefing original de esquadrias de janela/porta).', NULL),
(11, 'Porta/Gaveta de Móvel (Linha Moveleira)', 'MOVEL', 1, 'Identificado na planilha interna do usuário; mobiliário com perfil de alumínio, não é esquadria de edificação.', NULL);
